func (q *Queries) UpdateTransaction(ctx context.Context, arg UpdateTransactionParams) (Transaction, error) {
	row := q.db.QueryRow(ctx, updateTransaction,
		arg.Kind,
		arg.CategoryID,
		arg.AmountMinor,
		arg.OccurredOn,
		arg.Note,
		arg.ID,
		arg.HouseholdID,
	)
	var i Transaction
	err := row.Scan(
		&i.ID,
		&i.HouseholdID,
		&i.WalletID,
		&i.Kind,
		&i.CategoryID,
		&i.TransferID,
		&i.AmountMinor,
		&i.OccurredOn,
		&i.Note,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RecurringRuleID,
		&i.OccurrenceDate,
	)
	return i, err
}
